using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Media;
using System.Threading.Tasks;
using System.Windows.Forms;
namespace DoomSNESed {
    public sealed class AudioCapacityBar:Control {
        public int Used,Capacity;public string Caption="Import an audio file to measure its native allocation.";public Color Fill=Color.MediumPurple;
        public AudioCapacityBar(){DoubleBuffered=true;Height=52;Dock=DockStyle.Bottom;BackColor=Theme.Background;}
        protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);e.Graphics.DrawString(Caption,Font,Used>Capacity&&Capacity>0?Brushes.Salmon:Brushes.LightGray,8,3);e.Graphics.FillRectangle(Brushes.DimGray,8,30,Math.Max(1,Width-16),12);if(Capacity>0)using(var brush=new SolidBrush(Used>Capacity?Color.IndianRed:Fill))e.Graphics.FillRectangle(brush,8,30,(int)Math.Min(Width-16,(long)Math.Max(0,Width-16)*Used/Capacity),12);}
    }
    public sealed partial class ConverterForm {
        Action soundRefresh;readonly AudioProject audioChanges=new AudioProject();
        readonly ListBox musicMaps=new ListBox();
        readonly Dictionary<string,ImportedMusic> musicSources=new Dictionary<string,ImportedMusic>();
        SoundPlayer samplePlayer;MemoryStream sampleStream;
        void PrepareSmokeSection(string section){if(string.IsNullOrEmpty(section))return;tabs.SelectedTab=tabs.TabPages.Cast<TabPage>().First(p=>p.Text==section);if(section=="Sounds")soundRefresh();}
        void ShowReport(){tabs.SelectedTab=report.Parent as TabPage;}
        void RefreshAudioMaps(){if(musicMaps==null)return;musicMaps.Items.Clear();if(File.Exists(romPath.Text)){musicMaps.Items.Add(MusicTargets.Title);musicMaps.Items.Add(MusicTargets.Intermission);}if(wad!=null)foreach(string map in wad.Levels)musicMaps.Items.Add(map);else if(File.Exists(romPath.Text))try{foreach(var map in new Rom(romPath.Text,resources).Project.Maps)musicMaps.Items.Add(map.Name);}catch{}if(musicMaps.Items.Count>0)musicMaps.SelectedIndex=0;}
        static TextBox AudioReport(){return new TextBox{Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,BackColor=Theme.Background,ForeColor=Theme.Mint,BorderStyle=BorderStyle.None,Font=new Font("Segoe UI",10)};}
        void AddAudioTabs(){AddMusicTab();AddSoundTab();}
        void PlaySample(byte[] data){if(samplePlayer!=null)samplePlayer.Stop();if(samplePlayer!=null)samplePlayer.Dispose();if(sampleStream!=null)sampleStream.Dispose();sampleStream=new MemoryStream(WavImport.WaveFile(WavImport.Decode(data),11025));samplePlayer=new SoundPlayer(sampleStream);samplePlayer.Play();}
        void AddSoundTab(){
            var tab=new TabPage("Sounds"){BackColor=Theme.Panel};tabs.TabPages.Add(tab);var split=new SplitContainer{Dock=DockStyle.Fill,Width=1160,SplitterDistance=420,FixedPanel=FixedPanel.Panel1,BackColor=Theme.Border};tab.Controls.Add(split);var slots=new ListBox{Dock=DockStyle.Fill,BackColor=Theme.Background,ForeColor=Theme.Text,HorizontalScrollbar=true,BorderStyle=BorderStyle.None};var load=Theme.Button("Load native sample slots");load.Dock=DockStyle.Top;split.Panel1.Controls.Add(slots);split.Panel1.Controls.Add(load);var details=AudioReport();details.Text="Choose your base ROM, load the sample slots, then import a WAV.\r\n\r\nThe list groups effects sharing one native waveform. Replacing a slot also replaces every listed alias, including distance variants.\r\n\r\nWAV is mixed to mono and resampled to the selected effect playback rate and encoded to native BRR. Streamed effects have a 3321-byte SPC buffer. Resident effects retain their original SPC allocations.\r\n\r\nFit duration explicitly permits trimming the tail when the source is too long. Preview uses the retail SPC driver: select an effect alias to hear its actual pitch and envelope.";
            var aliases=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=310};var compensate=new CheckBox{Text="Preserve WAV pitch for selected effect",Checked=true,AutoSize=true};var options=new FlowLayoutPanel{Dock=DockStyle.Top,Height=128,Padding=new Padding(8)};var trim=new CheckBox{Text="Trim silence",Checked=true,AutoSize=true};var normalize=new CheckBox{Text="Normalize peak",Checked=true,AutoSize=true};var fit=new CheckBox{Text="Fit duration (trim tail)",Checked=false,AutoSize=true};var loop=new CheckBox{Text="Loop sample",Checked=false,AutoSize=true};options.Controls.Add(trim);options.Controls.Add(normalize);options.Controls.Add(fit);options.Controls.Add(loop);options.Controls.Add(compensate);options.Controls.Add(aliases);var actions=new FlowLayoutPanel{Dock=DockStyle.Top,Height=125,Padding=new Padding(8)};var import=Theme.Button("Import WAV...");var autoFit=Theme.Button("Auto-fit WAV to slot...");var original=Theme.Button("Play original in game pitch");var replacement=Theme.Button("Play replacement in game pitch");var reset=Theme.Button("Restore original");actions.Controls.Add(import);actions.Controls.Add(autoFit);actions.Controls.Add(original);actions.Controls.Add(replacement);actions.Controls.Add(reset);var meter=new AudioCapacityBar{Fill=Color.DarkOrange};split.Panel2.Controls.Add(details);split.Panel2.Controls.Add(meter);split.Panel2.Controls.Add(actions);split.Panel2.Controls.Add(options);Rom soundRom=null;
            Action show=delegate{var slot=slots.SelectedItem as NativeSound;if(slot==null)return;var change=audioChanges.Sounds.FirstOrDefault(s=>s.Wave==slot.Wave);meter.Used=change==null?slot.Bytes:change.Data.Length;meter.Capacity=slot.Turbo?3321:slot.Bytes;meter.Caption=(slot.Turbo?"Streamed SPC slot: ":"Resident SPC slot: ")+meter.Used+" / "+meter.Capacity+" B";meter.Invalidate();details.Text="Native waveform "+slot.Wave+"\r\n"+slot.Name+"\r\n\r\n"+(change==null?"Original ROM sample.":change.Name+"\r\n"+change.Report)+"\r\n\r\nShared aliases are replaced together. Playback keeps the game's original effect pitch and envelope.";};
            load.Click+=delegate{try{soundRom=new Rom(romPath.Text,resources);slots.Items.Clear();foreach(var slot in AudioRom.Sounds(soundRom.Bytes,resources))slots.Items.Add(slot);if(slots.Items.Count>0)slots.SelectedIndex=0;}catch(Exception ex){MessageBox.Show(this,ex.Message,"Sound samples");}};soundRefresh=()=>load.PerformClick();romPath.TextChanged+=delegate{StopAudio();soundRom=null;slots.Items.Clear();if(tabs.SelectedTab==tab&&File.Exists(romPath.Text))load.PerformClick();};tabs.SelectedIndexChanged+=delegate{if(tabs.SelectedTab==tab&&soundRom==null&&File.Exists(romPath.Text))load.PerformClick();};slots.SelectedIndexChanged+=delegate{aliases.Items.Clear();var selected=slots.SelectedItem as NativeSound;if(selected!=null)foreach(int effect in selected.Effects)aliases.Items.Add(effect+" - "+File.ReadAllLines(Path.Combine(resources,"AudioEffects.txt"))[effect]);if(aliases.Items.Count>0)aliases.SelectedIndex=0;show();};
            var lastWavs=new Dictionary<int,string>();Func<bool,Task> importWav=async automatic=>{var slot=slots.SelectedItem as NativeSound;if(slot==null)return;string path=null;if(automatic)lastWavs.TryGetValue(slot.Wave,out path);if(path==null||!File.Exists(path))using(var dialog=new OpenFileDialog{Filter="WAV audio|*.wav"}){if(dialog.ShowDialog(this)!=DialogResult.OK)return;path=dialog.FileName;}lastWavs[slot.Wave]=path;if(automatic){trim.Checked=true;normalize.Checked=true;fit.Checked=true;compensate.Checked=true;}bool cut=trim.Checked,gain=normalize.Checked,shorten=fit.Checked,repeat=loop.Checked,tune=compensate.Checked;int effect=slot.Effects.Length==0?-1:slot.Effects[Math.Max(0,aliases.SelectedIndex)];try{Enabled=false;details.Text="Mixing, resampling and encoding native BRR...";var result=await Task.Run(delegate{int rate=11025;if(tune&&effect>=0){int measured;NativeAudio.Render(soundRom.Bytes,NativeAudio.SoundRam(soundRom.Bytes,slot,effect,null),1,effect,.15,out measured);Bin.Require(measured>0,"The selected effect did not play. Choose another alias or disable pitch compensation.");rate=measured;}var change=WavImport.Convert(path,slot,cut,gain,shorten,repeat,rate);change.Effect=effect;change.Report+=tune&&effect>=0?" Pitch compensated for effect "+effect+" at "+rate+" Hz. Other aliases retain their intentional pitch differences.":" Standard 11025 Hz encoding; native effects keep their original pitch variations.";return change;});audioChanges.Sounds.RemoveAll(s=>s.Wave==slot.Wave);audioChanges.Sounds.Add(result);AssetsChanged();show();}catch(Exception ex){details.Text="Sound import stopped: "+ex.Message;meter.Caption="Import stopped: see the sample report.";meter.Used=2;meter.Capacity=1;meter.Invalidate();}finally{Enabled=true;}};
            import.Click+=async delegate{await importWav(false);};autoFit.Click+=async delegate{await importWav(true);};
            original.Click+=delegate{try{var slot=slots.SelectedItem as NativeSound;if(slot!=null){int rate,effect=slot.Effects.Length==0?-1:slot.Effects[Math.Max(0,aliases.SelectedIndex)];Bin.Require(effect>=0,"This placeholder has no in-game effect; choose an assigned slot.");StopAudio();PlayWave(NativeAudio.Wave(NativeAudio.Render(soundRom.Bytes,NativeAudio.SoundRam(soundRom.Bytes,slot,effect,null),1,effect,3,out rate)));details.AppendText("\r\nNative effect playback: "+rate+" Hz; original envelope/pitch.");}}catch(Exception ex){MessageBox.Show(this,ex.Message,"Preview sound");}};replacement.Click+=delegate{try{var slot=slots.SelectedItem as NativeSound;if(slot==null)return;var change=audioChanges.Sounds.FirstOrDefault(s=>s.Wave==slot.Wave);if(change!=null){int rate,effect=slot.Effects.Length==0?-1:slot.Effects[Math.Max(0,aliases.SelectedIndex)];Bin.Require(effect>=0,"This placeholder has no in-game effect.");StopAudio();PlayWave(NativeAudio.Wave(NativeAudio.Render(soundRom.Bytes,NativeAudio.SoundRam(soundRom.Bytes,slot,effect,change.Data),1,effect,3,out rate)));details.AppendText("\r\nNative effect playback: "+rate+" Hz; original envelope/pitch.");}}catch(Exception ex){MessageBox.Show(this,ex.Message,"Preview sound");}};reset.Click+=delegate{var slot=slots.SelectedItem as NativeSound;if(slot==null)return;audioChanges.Sounds.RemoveAll(s=>s.Wave==slot.Wave);AssetsChanged();show();};FormClosed+=delegate{if(samplePlayer!=null){samplePlayer.Stop();samplePlayer.Dispose();}if(sampleStream!=null)sampleStream.Dispose();};
        }
        void ArrangeSections(SplitContainer oldSplit){
            var maps=new TabPage("Maps"){BackColor=Theme.Panel};var panel=new Panel{Dock=DockStyle.Left,Width=320};while(oldSplit.Panel1.Controls.Count>0){Control control=oldSplit.Panel1.Controls[0];oldSplit.Panel1.Controls.Remove(control);panel.Controls.Add(control);}maps.Controls.Add(new Label{Dock=DockStyle.Fill,Padding=new Padding(24),Text="1. Choose the base ROM. PWAD is optional for music, sounds and graphics.\n\n2. Select the maps to include, or click Auto configure below. Unused original map space is reclaimed for assets.\n\n3. Visit each asset tab to import artwork, music or sounds.\n\n4. Analyze allocations, then Build campaign.\n\n5. Play directly in DoomSNESRecomp, or use the .sfc with an emulator.\n\nYour original files stay unchanged.",ForeColor=Theme.Mint});maps.Controls.Add(panel);oldSplit.Panel1Collapsed=true;
            var projectButtons=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=90,Padding=new Padding(12)};var originalMode=Theme.Button("Use base ROM levels (no PWAD)");originalMode.Click+=delegate{wadPath.Clear();LoadWad();report.Text="ROM-only asset mode. Use Music, Sounds and Graphics; build preserves original maps and progression.";};projectButtons.Controls.Add(originalMode);var saveSetup=Theme.Button("Save converter setup...");var openSetup=Theme.Button("Open converter setup...");saveSetup.Click+=delegate{SaveSetup();};openSetup.Click+=delegate{OpenSetup();};projectButtons.Controls.Add(saveSetup);projectButtons.Controls.Add(openSetup);maps.Controls.Add(projectButtons);
            TabPage reportPage=report.Parent as TabPage;TabPage[] pages=tabs.TabPages.Cast<TabPage>().Where(p=>p!=reportPage).ToArray();tabs.TabPages.Clear();tabs.TabPages.Add(maps);foreach(TabPage page in pages)tabs.TabPages.Add(page);tabs.TabPages.Add(reportPage);tabs.SelectedTab=maps;
        }
    }
}
